/**
 * The frame with its printed Weakness / Resistance filled in. Only fills a frame that has neither
 * (so a catalog that does carry them always wins); never mutates the input.
 */
export function withPrintedWR<F extends CardFrame>(f: F): F {
  if (f.weaknesses?.length || f.resistances?.length) return f;
  const wr = PRINTED_WR[f.cardId];
  return wr ? { ...f, weaknesses: (wr.weaknesses ?? []).map((w) => ({ ...w })), resistances: (wr.resistances ?? []).map((w) => ({ ...w })) } : f;
}
